	@Test
	void everyEnabledRendererQueryParsesAndIsAccountedFor() throws Exception {
		Map<String, Integer> counts = new LinkedHashMap<>();
		List<String> failures = new ArrayList<>();
		int total = 0;
		try (java.util.stream.Stream<GeneratedQuery> generated = SparqlComprehensiveStreamingValidTest
				.generatedQueries()) {
			for (GeneratedQuery query : (Iterable<GeneratedQuery>) generated::iterator) {
				total++;
				counts.merge(query.category(), 1, Integer::sum);
				try {
					QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query.sparql(), null);
				} catch (RuntimeException problem) {
					failures.add(query.category() + ": " + problem.getMessage() + "\n" + query.sparql());
				}
			}
		}

		StringBuilder census = new StringBuilder("=== Renderer generator / Janino input census ===\n")
				.append("total=")
				.append(total)
				.append(" categories=")
				.append(counts.size())
				.append('\n');
		counts.forEach((category, count) -> census.append(String.format("%6d  %s%n", count, category)));
		Path target = Path.of("target", "generated-query-census.txt");
		Files.createDirectories(target.getParent());
		Files.writeString(target, census);

		assertThat(failures).as("every enabled generated query must parse").isEmpty();
		assertThat(counts).hasSize(ENABLED_CATEGORY_COUNT);
		assertThat(total).as("the deterministic deep corpus must not be silently capped away").isGreaterThan(10_000);
	}

	@Test
	void everyLocalGeneratedTupleQueryHasParityAndAnExplicitJaninoCoverageState() throws Exception {
		Map<String, CoverageCounts> coverage = new LinkedHashMap<>();
		List<String> failures = new ArrayList<>();
		List<String> capabilityDeclines = new ArrayList<>();
		int total = 0;
		try (java.util.stream.Stream<GeneratedQuery> generated = SparqlComprehensiveStreamingValidTest
				.generatedQueries()) {
			for (GeneratedQuery query : (Iterable<GeneratedQuery>) generated::iterator) {
				total++;
				CoverageCounts counts = coverage.computeIfAbsent(query.category(), ignored -> new CoverageCounts());
				counts.total++;
				ParsedQuery parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query.sparql(), null);
				if (!(parsed instanceof ParsedTupleQuery)) {
					counts.nonTuple++;
					continue;
				}
				if (containsService(parsed.getTupleExpr())) {
					counts.externalService++;
					continue;
				}

				boolean nondeterministic = isNondeterministic(query.sparql())
						|| hasOrderDependentSlice(query.sparql());
				boolean unordered = !query.sparql().toUpperCase(Locale.ROOT).contains("ORDER BY");
				List<String> expected = null;
				try {
					if (!nondeterministic) {
						expected = genericRows(query.sparql(), unordered);
					}
					resetMetricsOnly();
					List<String> actual = nativeRowsUntilClassified(query.sparql(), unordered);
					if (nondeterministic) {
						counts.nondeterministic++;
					} else if (!actual.equals(expected)) {
						failures.add(query.category() + " native/generic mismatch at generated index " + total
								+ "\nQUERY:\n" + query.sparql()
								+ "\nKERNELS: planned=" + plannedKernels() + " opened=" + openedKernels()
								+ " declined=" + declinedKernels()
								+ "\nGENERIC:\n" + expected + "\nNATIVE:\n" + actual);
					}
				} catch (RuntimeException problem) {
					failures.add(query.category() + " execution failed at generated index " + total + ": " + problem
							+ "\n" + query.sparql());
					continue;
				}
				// Leak witness: every adjacency-semijoin probe must be released when its query finishes. A held
				// probe pins a native read stamp and wedges the dataset close — the 2026-08-05 coverage hang was
				// exactly this, from kernel routes bypassing the cursor machinery that closes plan filters.
				if (AdjacencyIntersectionProbe.ACTIVE_PROBES.get() != 0) {
					StringBuilder leak = new StringBuilder("LEAKED semijoin probes after query:\n" + query.sparql());
					synchronized (AdjacencyIntersectionProbe.ACTIVE_TRACES) {
						for (Throwable trace : AdjacencyIntersectionProbe.ACTIVE_TRACES.values()) {
							java.io.StringWriter sw = new java.io.StringWriter();
							trace.printStackTrace(new java.io.PrintWriter(sw));
							leak.append("\n").append(sw);
						}
					}
					throw new AssertionError(leak.toString());
				}

				if (openedKernels() > 0L) {
					counts.opened++;
				} else if (declinedKernels() > 0L) {
					Set<String> reasons = declineReasons(query.sparql());
					// Explain evaluates a freshly prepared query. Its extra open may cross the async compilation
					// threshold and engage the kernel that the immediately preceding execution only scheduled. Re-read
					// the counters after collecting telemetry so one query cannot be classified from two different
					// specialization states.
					if (openedKernels() > 0L) {
						counts.opened++;
					} else if (reasons.isEmpty()) {
						failures.add(query.category() + " had an unclassified kernel decline\n" + query.sparql());
					} else if (reasons.stream().allMatch(NON_CAPABILITY_REASONS::contains)) {
						counts.noOpportunity++;
					} else {
						counts.capabilityDecline++;
						capabilityDeclines.add("index=" + total + " category=" + query.category() + " reasons="
								+ reasons + "\n" + query.sparql() + "\n---\n");
						for (String reason : reasons) {
							if (!NON_CAPABILITY_REASONS.contains(reason)) {
								counts.declineReasons.merge(reason, 1, Integer::sum);
							}
						}
					}
				} else {
					counts.noAttempt++;
				}
			}
		}

		String census = renderCoverageCensus(total, coverage);
		Path target = Path.of("target", "generated-janino-coverage-census.txt");
		Files.createDirectories(target.getParent());
		Files.writeString(target, census);
		Files.writeString(Path.of("target", "generated-janino-capability-declines.txt"),
				String.join("", capabilityDeclines));
		System.out.println(census);

		int accounted = coverage.values()
				.stream()
				.mapToInt(CoverageCounts::accounted)
				.sum();
		assertThat(failures)
				.as("generated-query Janino failures; census written to %s", target)
				.isEmpty();
		assertThat(capabilityDeclines)
				.as("all local tuple-plan shapes must be supported; full declines written beside %s", target)
				.isEmpty();
		assertThat(accounted).as("every generated query must have one explicit coverage state").isEqualTo(total);
		assertThat(coverage.values().stream().mapToInt(count -> count.opened).sum())
				.as("the shared corpus must exercise compiled Janino kernels")
				.isPositive();
	}

	@Test
	void fiftyPreviouslyUnsupportedQueriesHaveParityAndAreKernelEligible() {
		Map<Integer, GeneratedQuery> selected = new LinkedHashMap<>();
		Set<Integer> wanted = new LinkedHashSet<>();
		PREVIOUSLY_UNSUPPORTED_CORPUS.forEach(candidate -> wanted.add(candidate.index));
		int[] index = { 0 };
		try (java.util.stream.Stream<GeneratedQuery> generated = SparqlComprehensiveStreamingValidTest
				.generatedQueries()) {
			generated.forEach(query -> {
				int current = ++index[0];
				if (wanted.contains(current)) {
					selected.put(current, query);
				}
			});
		}

		assertThat(selected).hasSize(PREVIOUSLY_UNSUPPORTED_CORPUS.size());
		assertThat(PREVIOUSLY_UNSUPPORTED_CORPUS).hasSize(50);
		List<String> failures = new ArrayList<>();
		for (JaninoCorpusCase candidate : PREVIOUSLY_UNSUPPORTED_CORPUS) {
			GeneratedQuery query = selected.get(candidate.index);
			if (!candidate.category.equals(query.category())) {
				failures.add(candidate.label() + " moved to category " + query.category());
				continue;
			}
			boolean unordered = !query.sparql().toUpperCase(Locale.ROOT).contains("ORDER BY");
			List<String> expected = genericRows(query.sparql(), unordered);
			resetMetricsOnly();
			List<String> actual = nativeRowsUntilClassified(query.sparql(), unordered);
			if (!actual.equals(expected)) {
				failures.add(candidate.label() + " native/generic mismatch\nQUERY:\n" + query.sparql()
						+ "\nGENERIC:\n" + expected + "\nNATIVE:\n" + actual);
			}
			long opened = openedKernels();
			if (opened == 0L) {
				Set<String> reasons = declineReasons(query.sparql());
				if (openedKernels() == 0L
						&& (reasons.isEmpty() || !NON_CAPABILITY_REASONS.containsAll(reasons))) {
					failures.add(
							candidate.label() + " was neither opened nor an eligible semantic-tier proposal; reasons="
									+ reasons + "\nQUERY:\n" + query.sparql());
				}
			}
		}

		assertThat(failures).as("50-query generated-kernel capability corpus").isEmpty();
	}

	@Test
	void nestedScopeMinusQueriesUseSemanticNativePlans() {
		Map<Integer, GeneratedQuery> selected = generatedQueriesAt(1344, 1397);
		assertThat(selected).containsOnlyKeys(1344, 1397);

		for (Map.Entry<Integer, GeneratedQuery> entry : selected.entrySet()) {
			String query = entry.getValue().sparql();
			List<String> expected = genericRows(query, true);
			long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
			long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
			resetMetricsOnly();

			List<String> actual = nativeRowsUntilClassified(query, true);
			String explain = explain(query);
			Set<String> reasons = declineReasons(query);

			assertThat(actual).as("generated query %s answer parity", entry.getKey())
					.containsExactlyElementsOf(expected);
			assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
					.as("generated query %s must not use a generic host\n%s", entry.getKey(), explain)
					.isZero();
			assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get() - islandsBefore)
					.as("generated query %s must not use a generic island\n%s", entry.getKey(), explain)
					.isZero();
			assertThat(openedKernels() > 0L || (!reasons.isEmpty() && NON_CAPABILITY_REASONS.containsAll(reasons)))
					.as("generated query %s must open a specialized kernel or decline explicitly; reasons=%s\n%s",
							entry.getKey(), reasons, explain)
					.isTrue();
		}
	}

