	private List<String> genericRows(String query, boolean unordered) {
		System.setProperty(NATIVE_FLAG, "false");
		try {
			return rows(query, unordered);
		} finally {
			System.setProperty(NATIVE_FLAG, "true");
		}
	}

	private List<String> nativeRowsUntilClassified(String query, boolean unordered) {
		List<String> result = rows(query, unordered);
		for (int round = 1; round < KERNEL_WARMUP_RUNS && openedKernels() == 0L
				&& (plannedKernels() > 0L || declinedKernels() > 0L); round++) {
			try {
				assertThat(LmdbNativeJaninoCodegen.awaitCompilationsForTests(10, TimeUnit.SECONDS))
						.as("scheduled Janino compilation completed")
						.isTrue();
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new AssertionError("interrupted while waiting for Janino compilation", interrupted);
			}
			result = rows(query, unordered);
		}
		return result;
	}

	private List<String> rows(String query, boolean unordered) {
		List<String> result = new ArrayList<>();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			org.eclipse.rdf4j.query.TupleQuery prepared = connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			prepared.setMaxExecutionTime(QUERY_TIMEOUT_SECONDS);
			try (TupleQueryResult tupleResult = prepared.evaluate()) {
				while (tupleResult.hasNext()) {
					BindingSet row = tupleResult.next();
					List<String> bindings = new ArrayList<>();
					for (String name : row.getBindingNames()) {
						bindings.add(name + "=" + row.getValue(name));
					}
					Collections.sort(bindings);
					result.add(String.join("|", bindings));
				}
			}
		}
		if (unordered) {
			Collections.sort(result);
		}
		return result;
	}

	private Set<String> declineReasons(String query) {
		Set<String> reasons = new LinkedHashSet<>();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			org.eclipse.rdf4j.query.TupleQuery prepared = connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			prepared.setMaxExecutionTime(QUERY_TIMEOUT_SECONDS);
			Matcher matcher = KERNEL_DECLINE.matcher(
					prepared.explain(org.eclipse.rdf4j.query.explanation.Explanation.Level.Telemetry).toString());
			while (matcher.find()) {
				reasons.add(matcher.group(2));
			}
		}
		return reasons;
	}

	private String explain(String query) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return connection.prepareTupleQuery(QueryLanguage.SPARQL, query)
					.explain(org.eclipse.rdf4j.query.explanation.Explanation.Level.Telemetry)
					.toString();
		}
	}

	private static Map<Integer, GeneratedQuery> generatedQueriesAt(int... wantedIndices) {
		Set<Integer> wanted = new LinkedHashSet<>();
		for (int wantedIndex : wantedIndices) {
			wanted.add(wantedIndex);
		}
		Map<Integer, GeneratedQuery> selected = new LinkedHashMap<>();
		int[] index = { 0 };
		try (java.util.stream.Stream<GeneratedQuery> generated = SparqlComprehensiveStreamingValidTest
				.generatedQueries()) {
			generated.forEach(query -> {
				int current = ++index[0];
				if (wanted.contains(current)) {
					selected.put(current, query);
				}
			});
		}
		return selected;
	}

	private static boolean containsService(TupleExpr expression) {
		boolean[] found = { false };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {

			@Override
			public void meet(Service node) {
				found[0] = true;
			}
		});
		return found[0];
	}

	private static boolean isNondeterministic(String query) {
		String upper = query.toUpperCase(Locale.ROOT);
		return upper.contains("RAND(") || upper.contains("NOW(") || upper.contains("UUID(")
				|| upper.contains("STRUUID(") || upper.contains("BNODE(");
	}

	private static boolean hasOrderDependentSlice(String query) {
		String upper = query.toUpperCase(Locale.ROOT);
		return upper.contains("ORDER BY") && (upper.contains("LIMIT ") || upper.contains("OFFSET "));
	}

	private static String renderCoverageCensus(int total, Map<String, CoverageCounts> coverage) {
		StringBuilder out = new StringBuilder("=== Generated-query Janino coverage census ===\n")
				.append("total=")
				.append(total)
				.append(" categories=")
				.append(coverage.size())
				.append('\n')
				.append(String.format("%-24s %6s %6s %6s %6s %6s %6s %6s %6s%n",
						"category", "total", "opened", "decline", "no-opp", "no-try", "service", "non-tuple",
						"nondet"));
		coverage.forEach((category, count) -> out.append(String.format("%-24s %6d %6d %6d %6d %6d %6d %9d %6d%n",
				category, count.total, count.opened, count.capabilityDecline, count.noOpportunity, count.noAttempt,
				count.externalService, count.nonTuple, count.nondeterministic)));
		Map<String, Integer> reasons = new TreeMap<>();
		coverage.values()
				.forEach(count -> count.declineReasons
						.forEach((reason, number) -> reasons.merge(reason, number, Integer::sum)));
		if (!reasons.isEmpty()) {
			out.append("\n-- capability declines --\n");
			reasons.forEach((reason, number) -> out.append(String.format("%6d  %s%n", number, reason)));
		}
		return out.toString();
	}

	private static long plannedKernels() {
		return LmdbNativeKernelExecution.PLANNED.get()
				+ LmdbNativeKernelExecution.AGG_PLANNED.get();
	}

	private static long openedKernels() {
		return LmdbNativeKernelExecution.OPENED.get()
				+ LmdbNativeKernelExecution.AGG_OPENED.get();
	}

	private static long declinedKernels() {
		return LmdbNativeKernelExecution.DECLINED.get()
				+ LmdbNativeKernelExecution.AGG_DECLINED.get();
	}

	private static void resetMetricsOnly() {
		LmdbNativeKernelExecution.resetMetrics();
	}

	private void save(String key, String value) {
		savedProperties.putIfAbsent(key, System.getProperty(key));
		System.setProperty(key, value);
	}

	private static final class CoverageCounts {
		int total;
		int opened;
		int capabilityDecline;
		int noOpportunity;
		int noAttempt;
		int externalService;
		int nonTuple;
		int nondeterministic;
		final Map<String, Integer> declineReasons = new TreeMap<>();

		int accounted() {
			return opened + capabilityDecline + noOpportunity + noAttempt + externalService + nonTuple;
		}
	}

	record JaninoCorpusCase(int index, String category, String baselineReason) {
		String label() {
			return "index=" + index + " category=" + category + " baselineReason=" + baselineReason;
		}
	}
